---The authoritative battle mutation interface. Available only to scripts running on the server: spawn or remove battle units, move them, deal damage, alter bonuses, drop obstacles, append to the combat log, draw from the seeded RNG. Every call emits a network pack so clients receive the resulting state change.
---@class BattleServer
local BattleServer = {}

---Spawns a new battle unit described by the given UnitInfo. Returns the created unit.
---@param battle Battle # Battle in which the unit is created.
---@param info UnitInfo # Descriptor of the unit to spawn (creature type, side, position, ...).
---@return Unit
function BattleServer:addUnit(battle, info) end

---Heals the given unit by the provided amount of health points.
---@param battle Battle # Battle in which the unit is healed.
---@param unit Unit # Target unit.
---@param amount integer # Hit points to restore.
---@param level HealLevel # Heal tier (heal / resurrect / overheal).
---@param power HealPower # Persistence — one-battle vs permanent.
---@return integer, integer # Healed hit points, and the count of creatures resurrected.
function BattleServer:healUnit(battle, unit, amount, level, power) end

---Applies a UnitState mutation to the unit, optionally adjusting current health.
---@param battle Battle # Battle in which the unit is modified.
---@param unitState UnitState # New unit state to apply (returned by `Unit:copy`).
---@param healthDelta integer? # Optional health delta — positive heals, negative damages.
function BattleServer:changeUnit(battle, unitState, healthDelta) end

---Damages the unit, returning the actual damage dealt and the number of killed creatures.
---@param battle Battle # Battle in which damage is dealt.
---@param unit Unit # Target unit.
---@param damage integer # Damage points to deal (will be clamped to remaining health).
---@return integer, integer # Damage actually dealt, and the count of killed creatures.
function BattleServer:damageUnit(battle, unit, damage) end

---Removes the unit or its corpse from the battlefield.
---@param battle Battle # Battle the unit belongs to.
---@param unit Unit # Unit (alive or as corpse) to remove.
function BattleServer:removeUnit(battle, unit) end

---Removes the given obstacle from the battlefield.
---@param battle Battle # Battle the obstacle belongs to.
---@param obstacle Obstacle # Obstacle to remove.
function BattleServer:removeObstacle(battle, obstacle) end

---Moves the unit to the destination hex.
---@param battle Battle # Battle in which the unit is moved.
---@param unit Unit # Unit to move.
---@param destination BattleHex # Target hex of the move.
---@param isTeleport boolean # Pass true to use teleport semantics (no path walk).
function BattleServer:moveUnit(battle, unit, destination, isTeleport) end

---Appends a formatted log entry to the battle log.
---@param battle Battle # Battle whose log is being appended.
---@param message MetaString # Formatted log line (use `MetaString`).
function BattleServer:appendLog(battle, message) end

---Returns whether netpack changes should be described in the battle log.
---@return boolean
function BattleServer:describeChanges() end

---Removes the listed bonuses from the unit.
---@param battle Battle # Battle the unit belongs to.
---@param unit Unit # Unit whose bonuses are removed.
---@param bonusList BonusList # Bonuses to remove from the unit.
function BattleServer:removeUnitBonuses(battle, unit, bonusList) end

---Adds a bonus described by the descriptor to the unit.
---@param battle Battle # Battle the unit belongs to.
---@param unit Unit # Unit to add the bonus to.
---@param descriptor BonusDescriptor # BonusDescriptor that creates the bonus.
---@param cumulative boolean # Pass true to stack with existing same-source bonus, false to update in-place.
function BattleServer:addUnitBonus(battle, unit, descriptor, cumulative) end

---Adds a bonus to the battle-wide bonus set.
---@param battle Battle # Battle to attach the bonus to.
---@param descriptor BonusDescriptor # BonusDescriptor that creates the bonus.
function BattleServer:addBattleBonus(battle, descriptor) end

---Creates a new obstacle described by the descriptor on the battlefield.
---@param battle Battle # Battle the obstacle is placed in.
---@param descriptor SpellObstacleDescriptor # SpellObstacleDescriptor describing the obstacle to create.
function BattleServer:addObstacle(battle, descriptor) end

---Performs a catapult attack against the given wall section, dealing the supplied damage.
---@param battle Battle # Battle in which the catapult attack happens.
---@param attacker Unit # Unit performing the catapult attack, or nil for spell-caused attacks.
---@param attackedPart WallPart # Wall section to attack.
---@param damageDealt integer # Damage to apply to the wall section.
function BattleServer:catapultAttack(battle, attacker, attackedPart, damageDealt) end

---Returns a server-side random integer in the inclusive range [low, high].
---@param low integer # Inclusive lower bound.
---@param high integer # Inclusive upper bound.
---@return integer # Random integer in [low, high].
function BattleServer:rngInt(low, high) end

---Rolls the same chance many times over and returns how many succeeded. Use this rather than a loop over `rngInt` for abilities that roll once per creature in a stack, which can number in the thousands.
---@param trials integer # How many independent chances are rolled.
---@param chance number # Chance of each one succeeding, from 0 to 1.
---@return integer # How many of them succeeded.
function BattleServer:rngBinomial(trials, chance) end

---Rolls a chance-based combat ability. Use this rather than `rngInt` for abilities that trigger with a percentage chance - it draws from the per-army biased sequence
---@param battle Battle # Battle the acting unit fights in.
---@param actor Unit # Unit whose ability is being rolled.
---@param percentageChance integer # Chance to succeed, in percent.
---@return boolean # True if the ability triggers.
function BattleServer:rollCombatAbility(battle, actor, percentageChance) end

---Casts a spell as a passive ability of the caster: announces it so that clients play its animation and sound, filters the targets through the spell's own immunity rules, and applies its effects with the given magnitude. Casting this way never fires a combat event, so a script that casts cannot re-enter itself.
---@param battle Battle # Battle the spell is cast in.
---@param caster Unit # Unit whose ability casts the spell.
---@param spell Spell # Spell to cast.
---@param target Unit[] # Units the spell is aimed at.
---@param effectValue integer # Magnitude handed to the spell's effects, for spells that take one.
function BattleServer:castSpell(battle, caster, spell, target, effectValue) end

---Applies the effects of a spell to the given units, and nothing else. Unlike casting the spell, the target list is used as given rather than expanded through the spell's range, magic resistance and magic mirror are not rolled, countering effects are not removed, and no spell animation or battle log entry is produced. Use it for abilities that behave as if the spell were already in effect.
---@param battle Battle # Battle the spell is applied in.
---@param caster Unit # Unit acting as the caster. Its stats scale the effects.
---@param spell Spell # Spell whose effects are applied.
---@param target Unit[] # Units to affect.
---@param spellLevel integer # Mastery level the effects are applied at.
---@param effectDuration integer # How many turns timed effects of the spell last.
---@param ignoreImmunity boolean # Pass true to affect units that are immune to the spell.
function BattleServer:applySpellEffects(battle, caster, spell, target, spellLevel, effectDuration, ignoreImmunity) end

---Plays a one-shot animation on the battlefield. Changes no game state, so use it to give a visual to a change the script made itself. The animation plays after whatever is currently animating has finished, rather than overlapping it. A deferred animation instead plays together with the animations of the next change the script makes, e.g. the flinch of a unit it damages right after - and is dropped if no such change follows.
---@param battle Battle # Battle the animation is played in.
---@param target Destination[] # Units and hexes the animation is played on, one copy each.
---@param animation string # Resource name of the animation to play, e.g. `SP06_`.
---@param sound string # Resource name of the sound to play alongside it, or an empty string for none.
---@param transparency number # Opacity of the animation, from 0 for invisible to 1 for opaque.
---@param deferred boolean? # Pass true to hold the animation back until the next change the script makes, so that both play at once.
function BattleServer:showBattleAnimation(battle, target, animation, sound, transparency, deferred) end

---Makes the client play back pending unit changes. Needed after adding or removing units outside of an attack, which otherwise produce no animation.
---@param battle Battle # Battle whose units were changed.
function BattleServer:refreshBattleUnits(battle) end

---A single effect contributing to target abilities (e.g. +5 attack, immunity to fire spells). Carries type, value, source, duration, stacking key. Scripts read bonuses through `getBonuses(...)` and construct new ones via addUnitBonus or addBattleBonus in ServerCallback.
---@class Bonus
local Bonus = {}

---Returns the bonus type as its JSON key.
---@return string
function Bonus:getType() end

---Returns the integer magnitude of the bonus.
---@return integer
function Bonus:getVal() end

---Returns the bonus subtype as a JSON key (the meaning depends on getType).
---@return string
function Bonus:getSubtype() end

---Returns the JSON key identifying the entity that granted this bonus.
---@return string
function Bonus:getSourceID() end

---Returns the source category (artifact, creature ability, spell, ...) of the bonus.
---@return BonusSource
function Bonus:getSource() end

---Returns the kind of combat the bonus is limited to. A bonus that applies to melee only is silently absent while shooting, and the other way round.
---@return BonusLimitEffect
function Bonus:getEffectRange() end

---Returns the list of duration flags currently set on the bonus.
---@return BonusDuration[]
function Bonus:getDuration() end

---Returns how the value combines with other bonuses (additive, percent, base number, ...).
---@return BonusValueType
function Bonus:getValType() end

---Returns the stacking key — bonuses with the same key from the same source do not stack.
---@return string
function Bonus:getStacking() end

---Returns the remaining turns until the bonus expires (0 if not turn-limited, only active if duration is set accordingly).
---@return integer
function Bonus:getTurnsRemain() end

---True if the bonus is hidden from the player's interface display.
---@return boolean
function Bonus:isHidden() end

---Returns the bonus's extra parameters encoded as a single integer (0 if none).
---@return integer
function Bonus:getParametersAsNumber() end

---Returns the bonus's extra parameters as a list of integers (empty if not stored as an array).
---@return integer[]
function Bonus:getParametersAsVector() end

---Configuration for a Bonus that scripts hand to ServerCallback `addUnitBonus` or `addBattleBonus`. Fields mirror the JSON bonus definition. See bonus docs for more details.
---@class BonusDescriptor
---@field val integer # Numeric magnitude of the bonus (interpreted per `valueType`).
---@field turns integer # Remaining duration in turns; relevant for the N_TURNS / N_DAYS durations.
---@field hidden boolean # If true, the bonus is not shown in the unit's bonus list UI.
---@field stacking string # Stacking key — bonuses sharing it overwrite rather than accumulate.
---@field description string # Optional human-readable description (used by tooltips when shown). Overrides generic description for this bonus type.
---@field icon string # Optional icon name shown next to the bonus in the UI. Overrides generic icon for this bonus type.
---@field type any # Bonus type name (e.g. PRIMARY_SKILL, FIRE_IMMUNITY). See Bonus types documentation.
---@field subtype any # Sub-selector that narrows the type (e.g. specific creature, school, primary stat).
---@field valueType any # How `val` is combined with other bonuses: additive, base, percent-of-..., independent min/max.
---@field effectRange any # Spatial scope the bonus applies in (e.g. ranged-only or melee-only).
---@field duration any # When the bonus expires — permanent, one-battle, n-turns, until-attacked, etc.
---@field sourceType any # Origin class (artifact, spell effect, secondary skill, …) — drives source-based dispels.
---@field sourceID any # Identifier of the specific source within its sourceType.
---@field targetSourceType any # Source type the bonus is restricted to act upon (used by hero specialty bonuses).
---@field addInfo any # Optional auxiliary payload — meaning depends on the bonus type.
---@field limiters any # JSON-defined limiter chain that definea whether the bonus applies to a given bearer.
---@field propagator any # Rule for propagating the bonus upwards for area effect (army-wide, player-wide, …).
---@field updater any # Rules for recalculation of bonus parameters (e.g. scales with stack count).
---@field propagationUpdater any # Updater applied to bonuses produced by this one's propagator.
local BonusDescriptor = {}

---Which bonuses of a bearer a query is about, handed to `getBonuses`, `getBonusesValue` and `hasBonuses` as a plain table. Every field left out widens the answer, so `{}` asks for all of them.
---@class BonusFilter
---@field type string? # Bonus type to look for, by its json key.
---@field subtype string? # Subtype to look for, by its json key. Requires a type.
---@field sourceType BonusSource? # Where the bonus has to come from - an artifact, a spell effect, ...
---@field shooting boolean? # Kind of blow the bonus has to count for - pass the `shooting` flag of the attack. Bonuses limited to the other kind are left out, those limited to neither always count.
local BonusFilter = {}

---A collection of Bonus values returned by `getBonuses(...)`. Use `size()` and `getBonus(index)` to iterate. A copy of the engine's internal list at the moment of the call — changes to holder afterwards will not affect this snapshot.
---@class BonusList
local BonusList = {}

---Returns the number of bonuses in this list.
---@return integer
function BonusList:size() end

---Computes total value of bonuses in the list, accounting for bonus value types
---@return integer
function BonusList:totalValue() end

---Returns the bonuses of this list the predicate accepts. Use to narrow a list down before `totalValue`, which combines what is left by the rules of the engine.
---@param predicate fun(b: Bonus): boolean # Selector — called for each bonus of the list; bonus is kept when it returns true.
---@return BonusList # Bonuses for which the predicate returned true.
function BonusList:filter(predicate) end

---Returns the bonus at the given 1-based index. Aborts the script if the index is out of range.
---@param index integer # 1-based position of the bonus to fetch.
---@return Bonus # Bonus stored at the given position.
function BonusList:getBonus(index) end

---A building of a town, as `TownInstance:getBuildings` reports it.
