---The global `ENUM` table — string->integer constants scripts use to avoid magic numbers. Each field below is a named group; the runtime value is a Lua table whose keys are the constant names.
---@class Enums
---@field HealLevel HealLevel # Outcome categories for the heal action: plain heal / resurrect / overheal.
---@field HealPower HealPower # Persistence of healing effects: one-battle vs permanent.
---@field SpellCastProblem SpellCastProblem # Error codes returned from spell-cast validation.
---@field AimType AimType # Targeting modes a spell can require: none, creature, obstacle, location.
---@field BonusDuration BonusDuration # Lifetime selectors used by Bonus / BonusDescriptor `duration`.
---@field BonusSource BonusSource # Origin classes used by Bonus / BonusDescriptor `sourceType`.
---@field BonusValueType BonusValueType # Combination rules used by Bonus / BonusDescriptor `valueType`.
---@field BonusLimitEffect BonusLimitEffect # Kinds of combat a bonus is limited to, used by Bonus `effectRange`.
---@field ObstacleType ObstacleType # Obstacle categories used by SpellObstacleDescriptor `obstacleType`.
---@field WallPart WallPart # Town-wall sections referenced by siege APIs and `catapultAttack`.
---@field BattleSide BattleSide # Battlefield side identifiers: none / attacker / defender.
---@field Difficulty Difficulty # Game difficulty levels, named after chess pieces (pawn = easiest, king = hardest).
---@field PrimarySkill PrimarySkill # The four primary hero skills.
---@field PlayerColor PlayerColor # Player colours, plus the neutral owner used by unowned objects.
---@field PlayerStatus PlayerStatus # Whether a player is still playing, has won, or has lost.
local Enums = {}

---Outcome categories for the heal action: plain heal / resurrect / overheal.
---@enum HealLevel
local HealLevel = {
    ---Standard healing — capped at the stack's current size, does not revive dead.
    heal = 0,
    ---Brings dead creatures in the stack back, up to the starting count.
    resurrect = 1,
    ---Allows increasing size of stack past the starting count.
    overheal = 2,
}

---Persistence of healing effects: one-battle vs permanent.
---@enum HealPower
local HealPower = {
    ---Resurrected troops disapper when the battle ends.
    oneBattle = 0,
    ---Resurrected troops persist into the post-battle stack state.
    permanent = 1,
}

---Error codes returned from spell-cast validation.
---@enum SpellCastProblem
local SpellCastProblem = {
    ---There is no hero available to cast the spell.
    noHeroToCastSpell = 1,
    ---The caster has already used their per-turn cast allowance.
    castsPerTurnLimit = 2,
    ---The caster does not carry a spellbook.
    noSpellbook = 3,
    ---The spell is not present in the caster's spellbook.
    heroDoesntKnowSpell = 4,
    ---The caster does not have enough mana for this spell.
    notEnoughMana = 5,
    ---An adventure-map spell was attempted in battle context.
    advmapSpellInsteadOfBattleSpell = 6,
    ---The caster's wisdom is too low for the spell's level.
    spellLevelLimitExceeded = 7,
    ---Dispel was cast but there are no eligible spells to remove.
    noSpellsToDispel = 8,
    ---No legal target was selected for the spell.
    noAppropriateTarget = 9,
    ---The chosen target unit is immune to this spell.
    stackImmuneToSpell = 10,
    ---The selected target is not valid for this spell's AimType.
    wrongSpellTarget = 11,
    ---Spells may not be cast during the tactic phase.
    ongoinTacticPhase = 12,
    ---Magic is suppressed on this battlefield (anti-magic terrain or effect).
    magicIsBlocked = 13,
}

---Targeting modes a spell can require: none, creature, obstacle, location.
---@enum AimType
local AimType = {
    ---Spell takes no target - massive spells that cast directly when selected.
    nothing = 0,
    ---Spell targets one or more units on the battlefield.
    creature = 1,
    ---Spell targets an existing obstacle.
    obstacle = 2,
    ---Spell targets one or more battlefield hexes (no unit required).
    location = 3,
}

---Lifetime selectors used by Bonus / BonusDescriptor `duration`.
---@enum BonusDuration
local BonusDuration = {
    ---Lasts forever (until explicitly removed).
    permanent = 1,
    ---Expires at the end of the current battle.
    oneBattle = 2,
    ---Expires after end of current in-game day.
    oneDay = 4,
    ---Expires after end of current in-game week.
    oneWeek = 8,
    ---Expires after N battle turns.
    nTurns = 16,
    ---Expires after N in-game days.
    nDays = 32,
    ---Expires the first time the bearer is attacked.
    untilBeingAttacked = 64,
    ---Expires the first time the bearer makes any attack.
    untilAttack = 128,
    ---Expires when the bearer's unit gets to act.
    stackGetsTurn = 256,
    ---Tied to a commander — expires when the commander dies.
    commanderKilled = 512,
    ---Expires when the bearer initiates an attack (not counter-attack).
    untilOwnAttack = 1024,
    ---Expires when the bearer takes spell or environmental damage.
    untilTakingIndirectDamage = 2048,
    ---Expires after the current attack-and-counter sequence resolves.
    untilAfterAttackSequence = 4096,
}

---Origin classes used by Bonus / BonusDescriptor `sourceType`.
---@enum BonusSource
local BonusSource = {
    ---Granted by an artifact definition. Does not stacks if hero has multiple of same artifacts
    artifact = 0,
    ---Granted by a specific equipped artifact instance. Stacks with multiple copies of same artifact
    artifactInstance = 1,
    ---Granted by a map-object type (e.g. Stables).
    objectType = 2,
    ---Granted by a specific instance of map object, stacks with each same object.
    objectInstance = 3,
    ---Innate to the creature type (e.g. dragon breath, undead).
    creatureAbility = 4,
    ---Native-terrain bonus (creature on its faction's home terrain).
    terrainNative = 5,
    ---Battlefield-terrain overlay bonus (magic plains, fiery fields, …).
    terrainOverlay = 6,
    ---Active spell effect on the bearer.
    spellEffect = 7,
    ---Built town structure providing the bonus.
    townStructure = 8,
    ---Hero primary skill (attack/defense/power/knowledge).
    heroBaseSkill = 9,
    ---Hero secondary skill level (Tactics, Offense, Wisdom, …).
    secondarySkill = 10,
    ---Hero specialty (creature affinity, spell affinity, etc.).
    heroSpecial = 11,
    ---Army composition bonus. Currently only used for morale.
    army = 12,
    ---Carry-over bonus from a campaign scenario.
    campaignBonus = 13,
    ---Stack-experience rank bonus.
    stackExperience = 14,
    ---Commander unit ability.
    commander = 15,
    ---Map-wide global effect. Defined in game settings.
    global = 16,
    ---Source not represented by another category.
    other = 17,
}

---Combination rules used by Bonus / BonusDescriptor `valueType`.
---@enum BonusValueType
local BonusValueType = {
    ---Adds to the base value, but after `percent to base`.
    additiveValue = 0,
    ---Adds the base value before any additive/percent steps.
    baseNumber = 1,
    ---Percentage applied to the running total of all sources combined.
    percentToAll = 2,
    ---Percentage applied to the base value only.
    percentToBase = 3,
    ---Percentage applied to the same-source subtotal.
    percentToSource = 4,
    ---Percentage applied only to bonuses from a matching targetSourceType.
    percentToTargetType = 5,
    ---Independent ceiling — wins if greater than the accumulated value.
    independentMax = 6,
    ---Independent floor — wins if smaller than the accumulated value.
    independentMin = 7,
}

---Kinds of combat a bonus is limited to, used by Bonus `effectRange`.
---@enum BonusLimitEffect
local BonusLimitEffect = {
    ---Applies to every kind of combat.
    noLimit = 0,
    ---Applies only while shooting.
    onlyDistanceFight = 1,
    ---Applies only in melee.
    onlyMeleeFight = 2,
}

---Obstacle categories used by SpellObstacleDescriptor `obstacleType`.
---@enum ObstacleType
local ObstacleType = {
    ---Small, randomly placed battlefield obstacles placed on start of the battle.
    usual = 0,
    ---Large obstacle blocking predefined part of the battlefield. At most one such obstacle is present on map.
    absolute = 1,
    ---Obstacle placed by a spell (Land Mine, Quicksand, Fire Wall, …).
    spellCreated = 2,
    ---Town-siege moat tiles.
    moat = 3,
}

---Town-wall sections referenced by siege APIs and `catapultAttack`.
---@enum WallPart
local WallPart = {
    ---No wall part. Returned for hexes outside the fortifications.
