    ---Central keep building, usually built by Citadel.
    keep = 0,
    ---Bottom tower of the town walls, usually built by Castle.
    bottomTower = 1,
    ---Destructible wall segment adjacent to bottom tower.
    bottomWall = 2,
    ---Destructible wall segment immediately below the gatehouse.
    belowGate = 3,
    ---Destructible wall segment immediately above the gatehouse.
    overGate = 4,
    ---Destructible wall segment adjacent to the upper tower.
    upperWall = 5,
    ---Upper tower of the town walls, usually built by Castle.
    upperTower = 6,
    ---Destructible town gate that can only be opened by defenders.
    gate = 7,
}

---Battlefield side identifiers: none / attacker / defender.
---@enum BattleSide
local BattleSide = {
    ---Not associated with any side.
    none = -1,
    ---The attacking army that initiated the battle. Equivalent to `left`
